// File Overview
// Combines browser modules in dependency order to create the deployable application bundle.

"use strict";

const fs = require("node:fs");
const path = require("node:path");

const projectRoot = path.resolve(__dirname, "..");
const outputDirectory = path.join(projectRoot, "dist");

// Bundle modules in dependency order, placing the entry point after its dependencies.
const bundles = Object.freeze({
  "application.bundle.js": Object.freeze([
    "browser/runtime.js",
    "browser/glowApp.js",
    "shared/ecologyConstants.js",
    "browser/gazeSupport.js",
    "browser/gazeEngine.js",
    "browser/sketchConfig.js",
    "shared/sharedEcologyRules.js",
    "browser/sharedEcologyClient.js",
    "browser/soundApp.js",
    "browser/attentionLogStore.js",
    "browser/life/predator.js",
    "browser/life/parasite.js",
    "browser/life/roamer.js",
    "browser/life/deepDiver.js",
    "browser/life/guardian.js",
    "browser/systems/worldSystem.js",
    "browser/lifeLogUi.js",
    "browser/systems/ecosystemStore.js",
    "browser/systems/interactionSystem.js",
    "browser/render/lifeView.js",
    "browser/render/worldView.js",
    "browser/render/interactionView.js",
    "browser/bootstrap.js",
  ]),
});

// Write source modules to the browser bundle in dependency order.
// This function was modified with the assistance of ChatGPT.
function buildBundle(filename, sources) {
  const seen = new Set();
  const output = [
    "// File Overview\n",
    "// Contains the generated browser runtime assembled from the project's source modules.\n",
    "// Rebuild this file after changing its sources; do not edit it directly.\n\n",
    "// Generated by scripts/build-browser-bundle.js. Do not edit directly.\n",
    "// After changing the source files below, run npm run build:browser.\n",
  ];
  for (const relativePath of sources) {
    if (seen.has(relativePath)) {
      throw new Error(`Duplicate bundle source: ${relativePath}`);
    }
    seen.add(relativePath);

    const absolutePath = path.join(projectRoot, relativePath);
    if (!fs.existsSync(absolutePath)) {
      throw new Error(`Missing bundle source: ${relativePath}`);
    }
    const contents = fs.readFileSync(absolutePath, "utf8").replace(/\r\n/g, "\n").trimEnd();
    const header = `// Source module: ${relativePath}\n`;

    output.push(header, contents, "\n;\n");
  }

  fs.writeFileSync(path.join(outputDirectory, filename), output.join(""), "utf8");
  console.log(`Built ${filename} from ${sources.length} sources.`);
}

fs.mkdirSync(outputDirectory, { recursive: true });
for (const [filename, sources] of Object.entries(bundles)) {
  buildBundle(filename, sources);
}
